// Prepara la richiesta all'LLM con l'evento ricevuto da Casa.
// Casa ha già scelto i candidati possibili: l'LLM sceglie tra questi e spiega perché.
const evento = $input.first().json.body;
const sistema = "Sei l'assistente di una casa condivisa. Dopo un cambio dei giorni in sede, in alcuni giorni una persona ha più faccende del solito (giorniPiuPieni). Per ognuno di quei giorni, scegli tra i candidati di quel giorno quali passare all'altra persona, solo per questa volta, in modo che la somma dei minuti passati si avvicini a daPassare senza superarlo di molto. Preferisci poche faccende lunghe a tante corte. Al massimo " + evento.massimoProposte + " in tutto. Per ogni scelta scrivi il motivo in italiano, in una frase breve, citando il giorno e i minuti. Se nessun candidato aiuta, rispondi con un elenco vuoto.";
const schema = {
  type: 'object',
  properties: {
    proposte: {
      type: 'array',
      maxItems: evento.massimoProposte,
      items: {
        type: 'object',
        properties: {
          choreId: { type: 'integer', enum: evento.candidati.map((c) => c.choreId) },
          motivo: { type: 'string' },
        },
        required: ['choreId', 'motivo'],
        additionalProperties: false,
      },
    },
  },
  required: ['proposte'],
  additionalProperties: false,
};
const dati = { giorniPiuPieni: evento.giorniPiuPieni, candidati: evento.candidati };
return [{
  json: {
    model: 'qwen3.5:4b',
    temperature: 0.2,
    max_tokens: 1000,
    // Senza ragionamento: con il ragionamento acceso il modello esaurisce i token prima di rispondere
    reasoning_effort: 'none',
    think: false,
    chat_template_kwargs: { enable_thinking: false },
    messages: [
      { role: 'system', content: sistema },
      { role: 'user', content: JSON.stringify(dati) },
    ],
    response_format: { type: 'json_schema', json_schema: { name: 'proposte', schema } },
  },
}];

// La risposta dell'LLM è un JSON in choices[0].message.content: se non si legge, nessuna proposta.
// La persona a cui passa la faccenda la decide il candidato scelto, non l'LLM.
const risposta = $input.first().json;
const evento = $('Evento da Casa').first().json.body;
let scelte = [];
try {
  scelte = JSON.parse(risposta.choices?.[0]?.message?.content ?? '{}').proposte ?? [];
} catch (e) {
  scelte = [];
}
const candidati = new Map(evento.candidati.map((c) => [c.choreId, c]));
const viste = new Set();
const proposte = [];
for (const s of scelte) {
  const c = candidati.get(s.choreId);
  if (!c || viste.has(s.choreId)) continue;
  viste.add(s.choreId);
  proposte.push({ choreId: c.choreId, chi: c.a, motivo: s.motivo });
}
return [{ json: { settimana: evento.settimana, prova: evento.prova === true, proposte } }];
